var ENT=[["Jupyter", "Interactive ML notebooks."], ["pandas", "DataFrame wrangling for features."], ["Cross-validation", "Honest generalization estimates."], ["SHAP", "Game-theoretic model explanations."], ["scikit-learn", "The friendly Python ML library: consistent APIs for classical algorithms."], ["PyTorch", "Meta's dynamic-graph deep learning framework researchers love."], ["TensorFlow", "Google's production deep learning platform with TFX pipelines."]];
